import{_ as i,c as t,o as a,ag as r}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Center of Gravity Analysis Guide","description":"","frontmatter":{"title":"Center of Gravity Analysis Guide"},"headers":[],"relativePath":"general/center-of-gravity-analysis-guide.md","filePath":"general/center-of-gravity-analysis-guide.md","lastUpdated":null}'),o={name:"general/center-of-gravity-analysis-guide.md"};function n(s,e,l,c,p,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="center-of-gravity-analysis-guide" tabindex="-1">Center of Gravity Analysis Guide <a class="header-anchor" href="#center-of-gravity-analysis-guide" aria-label="Permalink to &quot;Center of Gravity Analysis Guide&quot;">​</a></h1><h2 id="center-of-gravity-cog-analysis-guide" tabindex="-1">Center of Gravity (COG) Analysis Guide <a class="header-anchor" href="#center-of-gravity-cog-analysis-guide" aria-label="Permalink to &quot;Center of Gravity (COG) Analysis Guide&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The Center of Gravity (COG) is a pivotal concept in military theory and strategic planning, originating from Carl von Clausewitz&#39;s work. It represents the source of power that provides moral or physical strength, freedom of action, or will. Proper identification and manipulation of the COG can lead to significant strategic advantages and can be decisive in military operations.</p><p>Understanding the COG helps commanders focus their efforts on targets that will greatly affect the adversary&#39;s ability to conduct operations while protecting their own COG.</p><p>Joint Publication (JP) 1-02 defines COG as “those characteristics, capabilities, or sources of power from which a military force derives its freedom of action, physical strength, or will to fight.”</p><p>JP 3-0 defines COG as &quot;the source of power that provides moral or physical strength, freedom of action, or will to act.”</p><h3 id="objectives-and-detailed-questions" tabindex="-1">Objectives and Detailed Questions <a class="header-anchor" href="#objectives-and-detailed-questions" aria-label="Permalink to &quot;Objectives and Detailed Questions&quot;">​</a></h3><h3 id="identify-the-cog" tabindex="-1">Identify the COG <a class="header-anchor" href="#identify-the-cog" aria-label="Permalink to &quot;Identify the COG&quot;">​</a></h3><p>Accurately identifying the COG is critical for successful operational planning. This thoroughly analyzes friendly forces, adversaries, and other relevant actors such as host nations.</p><h4 id="friendly-cog" tabindex="-1"><strong>Friendly COG</strong>: <a class="header-anchor" href="#friendly-cog" aria-label="Permalink to &quot;**Friendly COG**:&quot;">​</a></h4><p>Assess our foundational strengths across various domains providing potential risks to mitigate.</p><ul><li><p><strong>Diplomatic</strong>: What international alliances and diplomatic relations fortify our position?</p></li><li><p><strong>Information</strong>: Which communication and propaganda efforts are most influential?</p></li><li><p><strong>Military</strong>: What units, capabilities, or systems are crucial for our success?</p></li><li><p><strong>Economic</strong>: What economic policies and resources ensure our sustained operations?</p></li><li><p><strong>Cyber</strong>: What are our capabilities for defending and attacking in the digital realm?</p></li><li><p><strong>Space</strong>: How do our satellite and space-based operations enhance our strategic goals?</p></li></ul><h4 id="adversary-cog" tabindex="-1"><strong>Adversary COG</strong>: <a class="header-anchor" href="#adversary-cog" aria-label="Permalink to &quot;**Adversary COG**:&quot;">​</a></h4><p>Pinpoint the adversary’s vital sources of power and potential targets:</p><ul><li><p><strong>Diplomatic</strong>: How do their international relationships affect their strategic capabilities?</p></li><li><p><strong>Information</strong>: What misinformation or psychological operations do they deploy?</p></li><li><p><strong>Military</strong>: Which military assets are essential to their operational success?</p></li><li><p><strong>Economic</strong>: Which economic dependencies are exploitable?</p></li><li><p><strong>Cyber</strong>: What are their cyber vulnerabilities?</p></li><li><p><strong>Space</strong>: Do they rely heavily on space-based assets?</p></li></ul><h4 id="host-nation-cog" tabindex="-1"><strong>Host Nation COG</strong>: <a class="header-anchor" href="#host-nation-cog" aria-label="Permalink to &quot;**Host Nation COG**:&quot;">​</a></h4><p>Assess the host nation’s pivotal strengths and vulnerabilities:</p><ul><li><p><strong>Diplomatic</strong>: What is the host nation’s stance, and how does it influence the conflict?</p></li><li><p><strong>Information</strong>: What are their capabilities in managing or disseminating information?</p></li><li><p><strong>Military</strong>: What military aspects of the host nation could influence their role in the conflict?</p></li><li><p><strong>Economic</strong>: How do the economic conditions affect their alignment in the conflict?</p></li><li><p><strong>Cyber</strong>: Assess the cyberinfrastructure and defenses of the host nation.</p></li><li><p><strong>Space</strong>: Evaluate the host nation’s reliance and capabilities on space-based assets.</p></li></ul><h3 id="steps-in-cog-analysis" tabindex="-1">Steps in COG Analysis <a class="header-anchor" href="#steps-in-cog-analysis" aria-label="Permalink to &quot;Steps in COG Analysis&quot;">​</a></h3><p>COG analysis involves a systematic approach to identify and exploit or protect centers of gravity.</p><h3 id="_1-define-the-operational-environment" tabindex="-1">1. Define the Operational Environment <a class="header-anchor" href="#_1-define-the-operational-environment" aria-label="Permalink to &quot;1. Define the Operational Environment&quot;">​</a></h3><p>Refer to the [(Political, Military, Economic, Social, Information, Infrastructure, Physical Environment, Time) framework to comprehensively understand the operational environment.</p><p><strong>Questions to consider:</strong></p><ul><li><p>What are the geographic, political, and societal characteristics affect potential COGs?</p></li><li><p>How do these elements advantage or disadvantage various actors?</p></li><li><p>What historical, cultural, and economic factors influence the conflict?</p></li></ul><h3 id="_2-determine-cogs-for-all-parties" tabindex="-1">2. Determine COGs for All Parties <a class="header-anchor" href="#_2-determine-cogs-for-all-parties" aria-label="Permalink to &quot;2. Determine COGs for All Parties&quot;">​</a></h3><p>Analyze the strengths and resources of friendly forces, adversaries, and other actors to hypothesize potential COGs.</p><p><strong>For each actor:</strong></p><ul><li><p>What are their primary sources of power?</p></li><li><p>How do these COGs support their strategic objectives?</p></li><li><p>Are multiple COGs at different levels (strategic, operational, tactical)?</p></li></ul><h3 id="_3-identify-critical-capabilities" tabindex="-1">3. Identify Critical Capabilities <a class="header-anchor" href="#_3-identify-critical-capabilities" aria-label="Permalink to &quot;3. Identify Critical Capabilities&quot;">​</a></h3><p>Critical capabilities are the primary abilities essential for a COG to function effectively. <strong>Focus on Actions (Verbs):</strong></p><ul><li><p>What can the COG do to achieve its objectives?</p></li><li><p>How does the COG exert influence or control? <strong>Strategic Contribution:</strong></p></li><li><p>How do these capabilities contribute to the actor&#39;s overall mission?</p></li><li><p>What would be the impact if these capabilities were degraded or neutralized? Examples of Critical Capabilities:</p></li></ul><p><strong>Military</strong>:</p><ul><li><p><strong>Project Power</strong>: Ability to deploy forces rapidly across different theaters.</p></li><li><p><strong>Sustain Operations</strong>: Maintain prolonged military campaigns. <strong>Information</strong>:</p></li><li><p><strong>Influence Public Perception</strong>: Shape narratives to gain support.</p></li><li><p><strong>Collect Intelligence</strong>: Gather actionable information on adversaries.</p></li></ul><h3 id="_4-determine-critical-requirements" tabindex="-1">4. Determine Critical Requirements <a class="header-anchor" href="#_4-determine-critical-requirements" aria-label="Permalink to &quot;4. Determine Critical Requirements&quot;">​</a></h3><p>Critical requirements are essential conditions, resources, and means for a critical capability to be fully operational.</p><p><strong>Focus on Resources (Nouns):</strong></p><ul><li><p>What resources are necessary for the critical capabilities?</p></li><li><p>Consider personnel, equipment, logistics, information, and infrastructure. <strong>Questions to consider:</strong></p></li><li><p>What logistical support is required?</p></li><li><p>Are there technological dependencies?</p></li><li><p>What are the training and readiness levels of personnel?</p></li></ul><h3 id="_5-identify-critical-vulnerabilities" tabindex="-1">5. Identify Critical Vulnerabilities <a class="header-anchor" href="#_5-identify-critical-vulnerabilities" aria-label="Permalink to &quot;5. Identify Critical Vulnerabilities&quot;">​</a></h3><p>Critical vulnerabilities are aspects of critical requirements that are deficient or vulnerable to direct or indirect attack.</p><p><strong>Focus on Weaknesses (Nouns):</strong></p><ul><li><p>Are there single points of failure?</p></li><li><p>Are there resource constraints or dependencies?</p></li><li><p>What are the physical or cyber vulnerabilities? <strong>Analysis:</strong></p></li><li><p>How can these vulnerabilities be exploited?</p></li><li><p>What would be the effect of exploiting these vulnerabilities on the COG?</p></li></ul><h3 id="_6-assess-and-prioritize-vulnerabilities" tabindex="-1">6. Assess and Prioritize Vulnerabilities <a class="header-anchor" href="#_6-assess-and-prioritize-vulnerabilities" aria-label="Permalink to &quot;6. Assess and Prioritize Vulnerabilities&quot;">​</a></h3><p>Use a weighting system to prioritize vulnerabilities based on their potential impact.</p><p><strong>Criteria for Assessment:</strong></p><ul><li><p><strong>Impact on COG (I)</strong>: How significantly would exploiting the vulnerability affect the COG?</p><ul><li><strong>Definition</strong>: Evaluate how a vulnerability affects the COG’s essential functionality or stability. This includes considering both the immediate impact and the potential for escalated disruptions or impairments over time.</li><li><strong>Application</strong>: Analysis should include a detailed examination of how the vulnerability might compromise the COG, considering scenarios of varying severity and their probable impacts on the COG&#39;s operations and objectives.</li></ul></li><li><p><strong>Attainability (A)</strong>: How feasible is exploiting the vulnerability with available resources?</p><ul><li><strong>Definition</strong>: Assesses the feasibility of exploiting or mitigating the vulnerability, given the available resources, capabilities, and situational constraints.</li><li><strong>Application</strong>: This involves evaluating the logistical, technological, and temporal resources required to address the vulnerability effectively. It should consider both the available resources and those that can be realistically obtained or mobilized.</li></ul></li><li><p><strong>Potential for Follow-Up Actions (F)</strong>:</p><ul><li><strong>Definition</strong>: Measures how addressing the vulnerability can provide strategic advantages or enable further actions that strengthen the COG or degrade an adversary&#39;s position.</li><li><strong>Application</strong>: Focus on identifying opportunities for additional strategic actions post-mitigation or exploitation. These could include enhanced security measures, increased political leverage, or any actions further weakening the opposition.</li></ul></li></ul><h4 id="scoring-system" tabindex="-1">Scoring System <a class="header-anchor" href="#scoring-system" aria-label="Permalink to &quot;Scoring System&quot;">​</a></h4><p>When establishing a scoring system for Center of Gravity (COG) analysis or any operational planning process, selecting a system ensures consistency, clarity, and precision is essential. The scoring system chosen should align with the specific objectives of the analysis and be easily understood by all participants. It is crucial to define each criterion clearly so planners can interpret the scores uniformly. This will help ensure that lower or higher scores consistently reflect greater or lesser advantages, risks, or priorities.</p><p>Two primary approaches to scoring are <strong>Traditional Scoring</strong> and <strong>Logarithmic Scoring</strong>. Each method has strengths and should be selected based on the analysis&#39;s complexity and depth.</p><h5 id="traditional-scoring" tabindex="-1">Traditional Scoring <a class="header-anchor" href="#traditional-scoring" aria-label="Permalink to &quot;Traditional Scoring&quot;">​</a></h5><p>Traditional scoring is a linear method where each criterion is rated on a simple scale, often between 1 and 5. This system is straightforward and effective for scenarios where planners need a basic method to compare and prioritize factors.</p><ul><li><p><strong>Scale</strong>: Rate each criterion using a scale, such as 1 to 5.</p></li><li><p><strong>Definition</strong>: Ensure that &quot;1&quot; is the least advantageous (or critical), while &quot;5&quot; is the most advantageous (or critical), or vice versa, depending on the criteria.</p></li><li><p><strong>Application</strong>: This method works well in contexts where the difference between each value (1, 2, 3, etc.) is linear, meaning that the advantage or disadvantage between successive values is equal.</p></li><li><p><strong>Example</strong>: If assessing the impact of logistical support, a rating of &quot;1&quot; might mean that the logistics are severely deficient, whereas a &quot;5&quot; indicates a highly efficient and effective logistical system.</p></li></ul><p><strong>Pros:</strong></p><ul><li><p>Simple and easy to understand.</p></li><li><p>It is ideal for straightforward evaluations with limited complexity.</p></li></ul><p><strong>Cons:</strong></p><ul><li><p>Does not emphasize significant differences between higher values.</p></li><li><p>It may lack nuance for complex, multidimensional problems.</p></li></ul><h5 id="logarithmic-scoring" tabindex="-1">Logarithmic Scoring <a class="header-anchor" href="#logarithmic-scoring" aria-label="Permalink to &quot;Logarithmic Scoring&quot;">​</a></h5><p>Logarithmic scoring is a more nuanced system that allows for greater differentiation between scores, especially at the higher end of the scale. This method is particularly useful when certain factors exponentially impact outcomes. For example, a small increase in a critical capability may drastically affect the overall mission, and logarithmic scoring captures that non-linear impact.</p><ul><li><p><strong>Scale</strong>: Rate each criterion using a logarithmic scale, such as (1, 3, 5, 8, 12).</p></li><li><p><strong>Definition</strong>: &quot;1&quot; represents the least advantageous (or least critical), and &quot;12&quot; represents the most advantageous (or most critical). The intervals between scores increase exponentially to account for larger differences in importance or impact.</p></li><li><p><strong>Application</strong>: This method is useful when a small increase in one criterion disproportionately affects the mission or operation. For example, moving from &quot;5&quot; to &quot;8&quot; might represent a far more significant improvement or risk than moving from &quot;1&quot; to &quot;3.&quot;</p></li><li><p><strong>Example</strong>: If evaluating cyber vulnerabilities, a &quot;1&quot; could signify minor risks that are unlikely to affect the overall mission, while a &quot;12&quot; would indicate severe vulnerabilities that, if exploited, could lead to mission failure.</p></li></ul><p><strong>Pros:</strong></p><ul><li><p>Captures non-linear relationships between factors.</p></li><li><p>Highlights critical differences between higher values, making it ideal for prioritizing high-stakes vulnerabilities.</p></li></ul><p><strong>Cons:</strong></p><ul><li><p>It is more complex to implement and may require additional explanation for users.</p></li><li><p>It can be harder to interpret when applied to simpler problems.</p></li></ul><p><strong>Calculating a Composite Score</strong></p><p>Once each criterion has been scored using the chosen system, a composite score should be calculated to prioritize vulnerabilities or opportunities. This involves summing the scores for each criterion to obtain an overall assessment of each factor&#39;s criticality or advantage. Higher composite scores typically indicate higher priority or criticality.</p><ul><li><p><strong>Composite Score Formula</strong>: Sum the scores across all criteria to determine the total score for each vulnerability or factor.</p></li><li><p><strong>Interpretation</strong>: Use the total score to rank vulnerabilities, prioritize mitigation efforts, or allocate resources more effectively.</p></li></ul><p>Example: If vulnerability A scores 30 and vulnerability B scores 18, vulnerability A should be addressed first due to its higher composite score.</p><p><strong>Best Practices for Scoring</strong></p><ol><li><p><strong>Consistency</strong>: Ensure that all participants use the same definitions for each score to maintain consistency across the analysis.</p></li><li><p><strong>Clarity</strong>: Define the meaning of each score at the outset, including whether higher or lower scores represent more or less advantage, risk, or priority.</p></li><li><p><strong>Adaptability</strong>: Be prepared to adjust the scoring system based on the specific requirements of the operation or mission.</p></li><li><p><strong>Training</strong>: Provide sufficient training to ensure that all analysts and planners understand how to apply the scoring system correctly.</p></li></ol><h3 id="composite-score-calculation" tabindex="-1">Composite Score Calculation <a class="header-anchor" href="#composite-score-calculation" aria-label="Permalink to &quot;Composite Score Calculation&quot;">​</a></h3><p>For both approaches, the composite score is the sum of the scores from each criterion (Impact on COG, Attainability, Potential for Follow-Up). A higher composite score suggests a higher-priority vulnerability that requires immediate attention.</p><h4 id="example-traditional-scoring-table" tabindex="-1">Example Traditional Scoring Table: <a class="header-anchor" href="#example-traditional-scoring-table" aria-label="Permalink to &quot;Example Traditional Scoring Table:&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Vulnerability</th><th>Impact on COG (I)</th><th>Attainability (A)</th><th>Follow-Up (F)</th><th>Score</th></tr></thead><tbody><tr><td>Atropia - Misinformation Campaign</td><td>5</td><td>4</td><td>3</td><td>12</td></tr><tr><td>Pineland - Cybersecurity Weakness</td><td>4</td><td>3</td><td>2</td><td>9</td></tr><tr><td>Atropia - Social Media Influence</td><td>3</td><td>3</td><td>4</td><td>10</td></tr></tbody></table><h4 id="example-logarithmic-scoring-table" tabindex="-1">Example Logarithmic Scoring Table: <a class="header-anchor" href="#example-logarithmic-scoring-table" aria-label="Permalink to &quot;Example Logarithmic Scoring Table:&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Vulnerability</th><th>Impact on COG (I)</th><th>Attainability (A)</th><th>Follow-Up (F)</th><th>Score</th></tr></thead><tbody><tr><td>Atropia - Misinformation Campaign</td><td>8</td><td>5</td><td>3</td><td>16</td></tr><tr><td>Pineland - Cybersecurity Weakness</td><td>5</td><td>3</td><td>3</td><td>11</td></tr><tr><td>Atropia - Social Media Influence</td><td>3</td><td>3</td><td>5</td><td>11</td></tr></tbody></table><h3 id="tools-and-techniques" tabindex="-1">Tools and Techniques <a class="header-anchor" href="#tools-and-techniques" aria-label="Permalink to &quot;Tools and Techniques&quot;">​</a></h3><ul><li><p><strong>SWOT Analysis](/general/pmesii-pt)</strong>: Evaluate Strengths, Weaknesses, Opportunities, and Threats for each COG.</p></li><li><p><strong><a href="/general/pmesii-pt.html">Framework</a></strong>: Analyze the operational environment comprehensively.</p></li><li><p><strong>Systems Thinking</strong>: Understand the interdependencies within the operational environment.</p></li><li><p><strong><a href="/general/structured-analytic-techniques-sats.html">Teaming</a></strong>: Use adversarial thinking to challenge assumptions and identify vulnerabilities.</p></li></ul><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li><p><strong>Continuous Assessment</strong>: Regularly update COG analysis to reflect changes in the operational environment.</p></li><li><p><strong>Interdisciplinary Approach</strong>: Incorporate insights from intelligence, logistics, cyber, and other relevant fields.</p></li><li><p><strong>Operational Security</strong>: Protect your COG analysis from adversary intelligence efforts.</p></li><li><p><strong>Commander&#39;s Guidance</strong>: Align COG analysis with the commander&#39;s intent and operational objectives.</p></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Planning] [Analysis]</p>',81)])])}const u=i(o,[["render",n]]);export{g as __pageData,u as default};
